from fractions import Fraction
import math
from collections import deque

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve_reachability(m, n, max_steps=10):
    """
    Checks if 1 is reachable starting from {m/n, n/m} using AM and HM.
    Returns (True, min_steps) if reachable within max_steps, otherwise (False, -1).
    """
    if m == n:
        # m=n=1, starts with {1, 1}
        return (True, 0)

    start_set = {Fraction(m, n), Fraction(n, m)}

    # Queue stores (current_set_of_numbers, steps)
    # We use frozenset to make the state hashable for memoization if needed, 
    # but since we are doing BFS level by level, we just track the set.
    queue = deque([(start_set, 0)])

    # Visited states are defined by the set of numbers present. 
    # Since the order doesn't matter, we store frozenset.
    visited = {frozenset(start_set)}

    while queue:
        current_set, steps = queue.popleft()

        if steps >= max_steps:
            continue

        # Check if 1 is in the current set
        if Fraction(1) in current_set:
            return (True, steps)

        numbers = list(current_set)
        n_count = len(numbers)

        # Generate all possible new numbers
        for i in range(n_count):
            for j in range(i + 1, n_count):
                x = numbers[i]
                y = numbers[j]

                # 1. Arithmetic Mean (AM)
                am = (x + y) / 2

                # 2. Harmonic Mean (HM)
                # HM = 2xy / (x+y). Since x+y is non-zero (m, n positive), this is safe.
                hm = 2 * x * y / (x + y)

                new_numbers = {am, hm}

                # Check if either new number is 1
                if am == 1 or hm == 1:
                    return (True, steps + 1)

                # Create the next state
                next_set_mutable = set(current_set)
                next_set_mutable.update(new_numbers)
                next_set = frozenset(next_set_mutable)

                if next_set not in visited:
                    visited.add(next_set)
                    queue.append((next_set, steps + 1))

    return (False, -1)

